// BUG-002: Coupon discount ignores item quantity
//
// Generated by EXEGEZIS 0.1.0 from test plan BUG-002 (sha256:cbd7fb4a773c…).
// Do not edit by hand. Regenerate with: exegezis compile --plan benchmarks/buggy-shop/cases/BUG-002/plan.json
// Standalone: it needs only @playwright/test. Run it with:
//   npx playwright test BUG-002.spec.ts
// Target: http://localhost:3000/ (override with the BASE_URL environment variable).
//
// Preconditions:
//   - buggy-shop is running at the target URL
//   - Every execution starts from a fresh browser context, hence a new session with an empty cart
//   - Coupon SAVE10 grants 10% off; Mechanical Keyboard costs $89.90

import { expect, test, type Response } from "@playwright/test";

test.use({
  baseURL: process.env["BASE_URL"] ?? "http://localhost:3000/",
  viewport: { width: 1280, height: 720 },
  locale: "en-US",
  timezoneId: "UTC",
  actionTimeout: 10000,
  navigationTimeout: 30000,
});

test("BUG-002: Coupon discount ignores item quantity", async ({ page }) => {
  test.setTimeout(120000);

  // Responses observed during the test, for HTTP assertions.
  const responses: Response[] = [];
  page.on("response", (response) => responses.push(response));

  await test.step("1. navigate /", async () => {
    await page.goto("/");
  });

  await test.step("2. click button \"Add Mechanical Keyboard to cart\"", async () => {
    await page.getByRole("button", { name: "Add Mechanical Keyboard to cart" }).click();
  });

  await test.step("3. anchor: The cart holds one keyboard", async () => {
    await expect(page.getByText("Mechanical Keyboard × 1")).toBeVisible({ timeout: 5000 });
  });

  await test.step("4. click button \"Add Mechanical Keyboard to cart\"", async () => {
    await page.getByRole("button", { name: "Add Mechanical Keyboard to cart" }).click();
  });

  await test.step("5. anchor: The cart holds two keyboards", async () => {
    await expect(page.getByText("Mechanical Keyboard × 2")).toBeVisible({ timeout: 5000 });
  });

  await test.step("6. fill label \"Coupon code\"", async () => {
    await page.getByLabel("Coupon code").fill("SAVE10");
  });

  await test.step("7. click button \"Apply coupon\"", async () => {
    await page.getByRole("button", { name: "Apply coupon" }).click();
  });

  await test.step("8. anchor: The coupon is accepted", async () => {
    await expect(page.getByRole("status")).toHaveText("Coupon SAVE10 applied", { timeout: 5000 });
  });

  await test.step("9. anchor: The API computes the subtotal of two keyboards ($179.80)", async () => {
    await expect.poll(() => lastResponse(responses, "POST", "/api/cart/coupon")?.status(), { timeout: 5000 }).toBe(200);
    await expect
      .poll(async () => jsonPointer(await lastResponse(responses, "POST", "/api/cart/coupon")?.json(), "/subtotalCents"), { timeout: 5000 })
      .toEqual(17980);
  });

  await test.step("10. expect: The API applies 10% of the subtotal as discount ($17.98)", async () => {
    await expect
      .poll(async () => jsonPointer(await lastResponse(responses, "POST", "/api/cart/coupon")?.json(), "/discountCents"), { timeout: 2000 })
      .toEqual(1798);
  });
});

/** Most recent response to `method path` observed so far (query string ignored). */
function lastResponse(responses: Response[], method: string | undefined, path: string): Response | undefined {
  for (let i = responses.length - 1; i >= 0; i--) {
    const response = responses[i]!;
    if (method !== undefined && response.request().method() !== method) continue;
    if (new URL(response.url()).pathname === path) return response;
  }
  return undefined;
}

/** Resolves an RFC 6901 JSON Pointer; undefined when the path does not exist. */
function jsonPointer(document: unknown, pointer: string): unknown {
  let current = document;
  for (const raw of pointer === "" ? [] : pointer.slice(1).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (current === null || typeof current !== "object" || !Object.hasOwn(current, key)) return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}
